  def icon(name, css: "size-5", stroke: 2, label: nil, filled: false)
    paths = ICONS.fetch(name.to_sym) { ICONS[:info] }
    aria = label ? { role: "img", "aria-label": label } : { "aria-hidden": "true" }
    tag.svg(paths.html_safe, xmlns: "http://www.w3.org/2000/svg", viewBox: "0 0 24 24", fill: filled ? "currentColor" : "none",
                             stroke: "currentColor", "stroke-width": stroke, "stroke-linecap": "round", "stroke-linejoin": "round",
                             class: css, focusable: "false", **aria)
  end
